"""Compare RBE workers without executing a TestRunner or compiler."""
from collections import defaultdict
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import sys

W = Path(os.environ["RUNNER_TEMP"]) / "rbe-platform-analysis"
MODE = sys.argv[1]
SOURCE = {"generic":"d41933c9999f4b63085b0cb5211d64dda74bcdc4",
          "separate":"35aa6228edcf1eb2bc07d6aa877b4317da27d68a"}[MODE]
assert subprocess.check_output(["git","rev-parse","HEAD"],text=True).strip() == SOURCE
MIXED = Path("test/rbe/mixed-native.targets").read_text().splitlines()
FILTERS = [f"//runsc/{p}:filter_precompiled" for p in ("boot/filter","gofer/fs/filter","gofer/net/filter")]
CONTROL = FILTERS + ["//runsc:version_test","//runsc/gofer/net:netgofer_test","//test/syscalls:uname_test_native"]
TARGETS = MIXED + CONTROL
endings = ["external/llvm+/runtimes/glibc/_objs/libm/m.pic.o","external/llvm+/runtimes/_objs/empty/empty.pic.o"]
valid_path = re.compile(r"bazel-out/[a-zA-Z0-9._+\-]+/(?:bin|testlogs)/[A-Za-z0-9._@+/=\-]+\Z")
output = W / f"{MODE}.json"
report = {"source":SOURCE,"closure_roots":TARGETS,"verified":False}
def save():
    text=json.dumps(report,sort_keys=True,indent=1)
    assert len(text)<=96000
    output.write_text(text+"\n")

query = ('let roots = deps(set('+' '.join(TARGETS)+')) in '
         'mnemonic("^TestRunner$",set('+' '.join(MIXED)+')) union '
         'mnemonic("^PrecompileSeccomp$",filter("runsc/(boot/filter|gofer/fs/filter|gofer/net/filter):filter_precompiled$",$roots)) union '
         'mnemonic("^CppCompile$",filter("llvm.*//runtimes(/glibc:libm|:empty)$",$roots))')
log = W / f"{MODE}.console"
graph = W / f"{MODE}.graph"
bep = W / f"{MODE}.bep"
bazel = [str(W/"bazel"),"--nosystem_rc","--nohome_rc","--host_jvm_args=-Xmx7g","aquery",
         "--config=source-presubmit-mixed","--remote_executor=","--remote_cache=","--jobs=4",
         "--spawn_strategy=local","--strategy=TestRunner=local","--build_event_json_file="+str(bep),
         "--output=jsonproto","--include_artifacts=true","--include_commandline",query]
save()
with graph.open("wb") as out, log.open("wb") as err:
    try:
        proc=subprocess.run(bazel,stdout=out,stderr=err,timeout=900,check=False)
        report["aquery_exit"]=proc.returncode
    except subprocess.TimeoutExpired:
        report["aquery_exit"]=124
text=log.read_text(errors="replace")
report["diagnostics"]=[name for name,patt in (
    ("conflict",r"conflict|generated by these conflicting actions"),
    ("unknown option",r"Unrecognized option|Unrecognized startup option"),
    ("fetch",r"Error downloading|Failed to fetch|Error fetching"),
    ("analysis",r"Analysis of target .* failed"),
    ("visibility",r"not visible"),
    ("toolchain",r"No matching toolchains|invalid registered")) if re.search(patt,text,re.I)]
report["error_lines"]=[line[:500] for line in text.splitlines() if line.startswith(("ERROR:", "WARNING: The following targets"))][:8]
events=[json.loads(l) for l in bep.read_text().splitlines()] if bep.exists() else []
report["execution_events"]=sum(any(k in e for k in ("action","testResult","testSummary")) for e in events)
save()
if report["aquery_exit"]: sys.exit(0)
data=json.loads(graph.read_bytes())
names={str(t["id"]):t["label"].removeprefix("@@//").removeprefix("//") for t in data["targets"]}
config={str(c["id"]):c["checksum"] for c in data["configuration"]}
frags={str(i["id"]):i for i in data["pathFragments"]}
def path(a):
    i=str(a["pathFragmentId"]);parts=[]
    while i in frags:
        f=frags[i];parts.append(f["label"]);i=str(f.get("parentId"))
    return "/".join(reversed(parts))
paths={str(a["id"]):path(a) for a in data["artifacts"]}
outputs=defaultdict(set)
report.update(tests={},seccomp=[],runtime_objects={s:[] for s in endings},conflicting_outputs=[])
for a in data.get("actions",[]):
    owner=names[str(a["targetId"])]
    mn=a["mnemonic"]; cfg=config.get(str(a.get("configurationId")))
    platform=a.get("executionPlatform","").removeprefix("@@")
    produced=[paths[str(i)] for i in a.get("outputIds",[])]
    props={p["key"]:p.get("value","") for p in a.get("executionInfo",[])}
    expected = {"amd64":"//tools/bazeldefs:linux_amd64","arm64":"//tools/bazeldefs:linux_arm64"} if MODE=="generic" else {c:"//test/rbe:ubuntu_"+c for c in ("amd64","arm64")}
    cpu=next((c for c,label in expected.items() if label==platform),None)
    for p in produced:
        outputs[p].add((cfg,a.get("actionKey"),platform))
    if mn=="TestRunner":
        label="//"+owner
        if label not in MIXED or not any(p.endswith("/test.log") for p in produced):continue
        fc=owner.startswith("sandboxexec/")
        match=(cpu==label.rsplit("_",1)[-1] and props.get("workload-isolation-type","oci")==("firecracker" if fc else "oci") and
               (not fc or (props.get("dockerUser")=="root" and props.get("network-enable-ipv6")=="true")))
        report["tests"][label]={"worker":platform,"matches":match}
    if mn=="PrecompileSeccomp":
        argv=a.get("arguments",[])
        report["seccomp"].append({"owner":owner,"worker":platform,"recognized":bool(cpu and argv and valid_path.fullmatch(argv[0]) and "filter_precompiled_gen_stubbed_bin" in argv[0]),
            "argv0":argv[0] if argv and valid_path.fullmatch(argv[0]) else None,"outputs":[p for p in produced if valid_path.fullmatch(p)]})
    for end in endings:
        for p in produced:
            if p.endswith("/"+end) and valid_path.fullmatch(p):
                report["runtime_objects"][end].append({"owner":owner,"path":p,"worker":platform,"configuration":cfg,"action_key":a.get("actionKey")})
for p,ids in outputs.items():
    if len(ids)>1 and valid_path.fullmatch(p):
        report["conflicting_outputs"].append(p)
report["conflict_count"]=len(report["conflicting_outputs"])
report["conflicting_outputs"]=report["conflicting_outputs"][:25]
report["verified"]=(not report["execution_events"] and len(report["tests"])==4 and all(v["matches"] for v in report["tests"].values()) and
    all(report["runtime_objects"].values()) and not report["conflict_count"] and
    {row["owner"] for row in report["seccomp"]}=={s[2:] for s in FILTERS} and all(row["recognized"] for row in report["seccomp"]))
save()
